var tipuesearch = {"pages":[{"title":" PEAKS ","text":"PEAKS Developer Info Jason Christopherson","tags":"home","loc":"index.html"},{"title":"peak_detect – PEAKS","text":"public interface peak_detect Attempts to locate local maxima (peaks), and local minima \n(valleys) within a signal. The code is a re-implementation of the peak detection routine \npresented by Eli Billauer, which can be found at \nhttps://billauer.co.il/blog/2009/01/peakdet-matlab-octave/. Contents Module Procedures peak_detect_r32 peak_detect_r64 Module Procedures private  subroutine peak_detect_r32(x, delta, maxind, maxvals, minind, minvals) The real32 implementation. Arguments Type Intent Optional Attributes Name real(kind=real32), intent(in) :: x (:) An N-element array containing the signal to analyze. real(kind=real32), intent(in) :: delta A threshold value that determines the sensitivity the algorithm has \nto discerning local maxima or minima from noise. integer(kind=int32), intent(out), allocatable :: maxind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local maxima. real(kind=real32), intent(out), allocatable :: maxvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local maxima. integer(kind=int32), intent(out), allocatable :: minind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local minima. real(kind=real32), intent(out), allocatable :: minvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local minima. private  subroutine peak_detect_r64(x, delta, maxind, maxvals, minind, minvals) The real64 implementation. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to analyze. real(kind=real64), intent(in) :: delta A threshold value that determines the sensitivity the algorithm has \nto discerning local maxima or minima from noise. integer(kind=int32), intent(out), allocatable :: maxind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local maxima. real(kind=real64), intent(out), allocatable :: maxvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local maxima. integer(kind=int32), intent(out), allocatable :: minind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local minima. real(kind=real64), intent(out), allocatable :: minvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local minima.","tags":"","loc":"interface\\peak_detect.html"},{"title":"peaks – PEAKS","text":"Uses iso_fortran_env Contents Interfaces peak_detect Interfaces public        interface peak_detect Attempts to locate local maxima (peaks), and local minima \n(valleys) within a signal. The code is a re-implementation of the peak detection routine \npresented by Eli Billauer, which can be found at \nhttps://billauer.co.il/blog/2009/01/peakdet-matlab-octave/. private  subroutine peak_detect_r32(x, delta, maxind, maxvals, minind, minvals) The real32 implementation. Arguments Type Intent Optional Attributes Name real(kind=real32), intent(in) :: x (:) An N-element array containing the signal to analyze. real(kind=real32), intent(in) :: delta A threshold value that determines the sensitivity the algorithm has \nto discerning local maxima or minima from noise. integer(kind=int32), intent(out), allocatable :: maxind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local maxima. real(kind=real32), intent(out), allocatable :: maxvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local maxima. integer(kind=int32), intent(out), allocatable :: minind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local minima. real(kind=real32), intent(out), allocatable :: minvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local minima. private  subroutine peak_detect_r64(x, delta, maxind, maxvals, minind, minvals) The real64 implementation. Arguments Type Intent Optional Attributes Name real(kind=real64), intent(in) :: x (:) An N-element array containing the signal to analyze. real(kind=real64), intent(in) :: delta A threshold value that determines the sensitivity the algorithm has \nto discerning local maxima or minima from noise. integer(kind=int32), intent(out), allocatable :: maxind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local maxima. real(kind=real64), intent(out), allocatable :: maxvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local maxima. integer(kind=int32), intent(out), allocatable :: minind (:) An allocatable array that will be allocated by this routine and \nfilled with the indices of the local minima. real(kind=real64), intent(out), allocatable :: minvals (:) An allocatable array that will be allocated by this routine and \nfilled with the local minima.","tags":"","loc":"module\\peaks.html"},{"title":"peaks.f90 – PEAKS","text":"Contents Modules peaks Source Code peaks.f90 Source Code module peaks use iso_fortran_env implicit none private public :: peak_detect interface peak_detect !! Attempts to locate local maxima (peaks), and local minima !! (valleys) within a signal. !! !! The code is a re-implementation of the peak detection routine !! presented by Eli Billauer, which can be found at !! https://billauer.co.il/blog/2009/01/peakdet-matlab-octave/. module procedure :: peak_detect_r32 module procedure :: peak_detect_r64 end interface contains ! ------------------------------------------------------------------------------ subroutine peak_detect_r32 ( x , delta , maxind , maxvals , minind , minvals ) !! The real32 implementation. real ( real32 ), intent ( in ) :: x (:) !! An N-element array containing the signal to analyze. real ( real32 ), intent ( in ) :: delta !! A threshold value that determines the sensitivity the algorithm has !! to discerning local maxima or minima from noise. integer ( int32 ), intent ( out ), allocatable :: maxind (:) !! An allocatable array that will be allocated by this routine and !! filled with the indices of the local maxima. real ( real32 ), intent ( out ), allocatable :: maxvals (:) !! An allocatable array that will be allocated by this routine and !! filled with the local maxima. integer ( int32 ), intent ( out ), allocatable :: minind (:) !! An allocatable array that will be allocated by this routine and !! filled with the indices of the local minima. real ( real32 ), intent ( out ), allocatable :: minvals (:) !! An allocatable array that will be allocated by this routine and !! filled with the local minima. ! Local Variables logical :: lookformax integer ( int32 ) :: i , n , nmax , nmin , mxpos , mnpos integer ( int32 ), allocatable :: maxibuffer (:), minibuffer (:) real ( real32 ), allocatable :: maxbuffer (:), minbuffer (:) real ( real32 ) :: this , mn , mx ! Initialization n = size ( x ) nmax = 0 nmin = 0 lookformax = . true . mn = huge ( delta ) mx = - huge ( delta ) allocate ( maxibuffer ( n )) allocate ( maxbuffer ( n )) allocate ( minibuffer ( n )) allocate ( minbuffer ( n )) ! Process do i = 1 , n this = x ( i ) if ( this > mx ) then mx = this mxpos = i end if if ( this < mn ) then mn = this mnpos = i end if if ( lookformax ) then if ( this < mx - delta ) then nmax = nmax + 1 maxibuffer ( nmax ) = mxpos maxbuffer ( nmax ) = mx mn = this mnpos = i lookformax = . false . end if else if ( this > mn + delta ) then nmin = nmin + 1 minibuffer ( nmin ) = mnpos minbuffer ( nmin ) = mn mx = this mxpos = i lookformax = . true . end if end if end do ! Handle the output allocate ( maxind ( nmax ), source = maxibuffer ( 1 : nmax )) allocate ( maxvals ( nmax ), source = maxbuffer ( 1 : nmax )) allocate ( minind ( nmin ), source = minibuffer ( 1 : nmin )) allocate ( minvals ( nmin ), source = minbuffer ( 1 : nmin )) end subroutine ! ------------------------------------------------------------------------------ subroutine peak_detect_r64 ( x , delta , maxind , maxvals , minind , minvals ) !! The real64 implementation. real ( real64 ), intent ( in ) :: x (:) !! An N-element array containing the signal to analyze. real ( real64 ), intent ( in ) :: delta !! A threshold value that determines the sensitivity the algorithm has !! to discerning local maxima or minima from noise. integer ( int32 ), intent ( out ), allocatable :: maxind (:) !! An allocatable array that will be allocated by this routine and !! filled with the indices of the local maxima. real ( real64 ), intent ( out ), allocatable :: maxvals (:) !! An allocatable array that will be allocated by this routine and !! filled with the local maxima. integer ( int32 ), intent ( out ), allocatable :: minind (:) !! An allocatable array that will be allocated by this routine and !! filled with the indices of the local minima. real ( real64 ), intent ( out ), allocatable :: minvals (:) !! An allocatable array that will be allocated by this routine and !! filled with the local minima. ! Local Variables logical :: lookformax integer ( int32 ) :: i , n , nmax , nmin , mxpos , mnpos integer ( int32 ), allocatable :: maxibuffer (:), minibuffer (:) real ( real64 ), allocatable :: maxbuffer (:), minbuffer (:) real ( real64 ) :: this , mn , mx ! Initialization n = size ( x ) nmax = 0 nmin = 0 lookformax = . true . mn = huge ( delta ) mx = - huge ( delta ) allocate ( maxibuffer ( n )) allocate ( maxbuffer ( n )) allocate ( minibuffer ( n )) allocate ( minbuffer ( n )) ! Process do i = 1 , n this = x ( i ) if ( this > mx ) then mx = this mxpos = i end if if ( this < mn ) then mn = this mnpos = i end if if ( lookformax ) then if ( this < mx - delta ) then nmax = nmax + 1 maxibuffer ( nmax ) = mxpos maxbuffer ( nmax ) = mx mn = this mnpos = i lookformax = . false . end if else if ( this > mn + delta ) then nmin = nmin + 1 minibuffer ( nmin ) = mnpos minbuffer ( nmin ) = mn mx = this mxpos = i lookformax = . true . end if end if end do ! Handle the output allocate ( maxind ( nmax ), source = maxibuffer ( 1 : nmax )) allocate ( maxvals ( nmax ), source = maxbuffer ( 1 : nmax )) allocate ( minind ( nmin ), source = minibuffer ( 1 : nmin )) allocate ( minvals ( nmin ), source = minbuffer ( 1 : nmin )) end subroutine ! ------------------------------------------------------------------------------ end module","tags":"","loc":"sourcefile\\peaks.f90.html"}]}